$cacheSerializedSetup = @'
const fs=require('node:fs'),path=require('node:path');
fs.copyFileSync('scripts/production-cache-race.py','scripts/fixtures/production-cache-race-v1.py');
let t=fs.readFileSync('scripts/production-cache-race.py','utf8');
t=t.replace('def run(index,cache,barrier,out):','def run(index,cache,barrier,completed,out):').replace("def synchronized_replace(a,b):barrier.wait(timeout=30);return replace(a,b)","def synchronized_replace(a,b):\n        barrier.wait(timeout=30)\n        if index:completed[index-1].wait(timeout=30)\n        try:return replace(a,b)\n        finally:completed[index].set()");
t=t.replaceAll('production-cache-race-protocol.json','production-cache-race-serialized-protocol.json').replaceAll('production-cache-race.json','production-cache-race-serialized.json');
t=t.replace("'encoderMocked':True,'expected'","'legalSchedule':'All writes finish; rename calls execute in index order using explicit events','encoderMocked':True,'expected'");
t=t.replace('barrier=multiprocessing.Barrier(4);out=multiprocessing.Queue();children=', 'barrier=multiprocessing.Barrier(4);completed=[multiprocessing.Event() for _ in range(4)];out=multiprocessing.Queue();children=').replace('args=(i,cache,barrier,out)','args=(i,cache,barrier,completed,out)');
fs.writeFileSync('scripts/production-cache-race.py',t);
const root=JSON.parse(fs.readFileSync('.dip-local/production-frozen-location.json')).root;fs.copyFileSync('scripts/production-cache-race.py',path.join(root,'scripts/production-cache-race.py'));fs.copyFileSync('scripts/fixtures/production-cache-race-v1.py',path.join(root,'scripts/fixtures/production-cache-race-v1.py'));
'@
node -e $cacheSerializedSetup
$productionPython=(Resolve-Path -LiteralPath '.dip-local/laya-env/Scripts/python.exe').Path
Set-Location -LiteralPath '.dip-local/production-frozen'
& $productionPython scripts/production-cache-race.py --protocol
& $productionPython scripts/production-cache-race.py
